    minRatio,
    lessThan(_maxLinearRatio),
    reason:
        '$label wrap is superlinear in input size: best doubling ratio '
        'across $_growthAttempts attempts is ${minRatio.toStringAsFixed(2)}x '
        '($baseCells -> ${baseCells * 2} cells)',
  );
